from pysat.solvers import Glucose3
import time

n = 12

# Variable: x[i][j][v] -> i*n*n + j*n + v + 1 (1-indexed for pysat)
def var(i, j, v):
    return i * n * n + j * n + v + 1

clauses = []

# 1. Each cell has at least one value (we'll use exactly-one via cardinality)
# For now, let's use the naive pairwise encoding for "at most one" and "at least one"

# At least one value per cell
for i in range(n):
    for j in range(n):
        clause = [var(i, j, v) for v in range(n)]
        clauses.append(clause)

# At most one value per cell (pairwise)
for i in range(n):
    for j in range(n):
        for v1 in range(n):
            for v2 in range(v1+1, n):
                clauses.append([-var(i, j, v1), -var(i, j, v2)])

# 2. Each row: each value appears exactly once
# At least one column per row per value
for i in range(n):
    for v in range(n):
        clause = [var(i, j, v) for j in range(n)]
        clauses.append(clause)

# At most one column per row per value
for i in range(n):
    for v in range(n):
        for j1 in range(n):
            for j2 in range(j1+1, n):
                clauses.append([-var(i, j1, v), -var(i, j2, v)])

# 3. Each column: each value appears exactly once
# At least one row per column per value
for j in range(n):
    for v in range(n):
        clause = [var(i, j, v) for i in range(n)]
        clauses.append(clause)

# At most one row per column per value
for j in range(n):
    for v in range(n):
        for i1 in range(n):
            for i2 in range(i1+1, n):
                clauses.append([-var(i1, j, v), -var(i2, j, v)])

# 4. Idempotent: x[i][i] = i
for i in range(n):
    clauses.append([var(i, i, i)])

# 5. QG3: x[x[i][j]][x[j][i]] = i
# If x[i][j] = a and x[j][i] = b, then x[a][b] = i
# ¬x_{i,j,a} ∨ ¬x_{j,i,b} ∨ x_{a,b,i}
qg3_count = 0
for i in range(n):
    for j in range(n):
        for a in range(n):
            for b in range(n):
                clauses.append([-var(i, j, a), -var(j, i, b), var(a, b, i)])
                qg3_count += 1

print(f"Total clauses: {len(clauses)}")
print(f"QG3 clauses: {qg3_count}")
print(f"Total variables: {n*n*n}")

# Solve
start = time.time()
solver = Glucose3()
for clause in clauses:
    solver.add_clause(clause)

result = solver.solve()
elapsed = time.time() - start
print(f"Result: {result}")
print(f"Time: {elapsed:.2f}s")

if result:
    model = solver.get_model()
    # Decode
    grid = [[0]*n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            for v in range(n):
                if model[var(i,j,v)-1] > 0:
                    grid[i][j] = v
                    break

    # Verify
    # Check Latin square
    for i in range(n):
        row = set(grid[i])
        col = set(grid[j][i] for j in range(n))
        assert len(row) == n, f"Row {i} not permutation: {grid[i]}"
        assert len(col) == n, f"Col {i} not permutation"

    # Check idempotent
    for i in range(n):
        assert grid[i][i] == i, f"Not idempotent at {i}: {grid[i][i]}"

    # Check QG3
    for i in range(n):
        for j in range(n):
            a = grid[i][j]
            b = grid[j][i]
            assert grid[a][b] == i, f"QG3 fails at ({i},{j}): grid[{a}][{b}] = {grid[a][b]} != {i}"

    print("All checks passed!")
    print("Grid:")
    for row in grid:
        print(row)

    # Flat list
    flat = [grid[i][j] for i in range(n) for j in range(n)]
    print("Flat:", flat)
else:
    print("UNSAT")
